"""Generate a reviewable course proposal from the unchanged exam source."""
import json
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1]
source = json.loads((ROOT / 'content.json').read_text(encoding='utf-8'))
# Every source question has one primary home; cross-topic revisions can link back.
modules = [
 ('Как устроена сеть', [1,3,5,6,21,22], [], 'Путь запроса → клиент и сервер → роли устройств и портов', 'Собрать схему офиса; провести пакет по уровням и выбрать устройство'),
 ('Канальный уровень и среда передачи', [17,19,20,23,24], [], 'Ethernet и PPP → медь и оптика → выбор линии связи', 'Изучить кадр и MAC-таблицу; подобрать среду для трёх объектов'),
 ('IPv4, IPv6 и подсети', [49,50,51], [3,5,13,14,15], 'IPv4 и маска → сеть и broadcast → деление подсетей → IPv6', 'Двоичная маска, случайные задачи и настройка адресов в конструкторе'),
 ('VLAN и коммутация', [9], [6,7], 'Широковещательный домен → access → trunk', 'Назначить VLAN портам; проследить кадр; исправить trunk'),
 ('Маршрутизация', [2,52,53,54], [1,2,8,16,17,18,19,20,28], 'Шлюз и таблица маршрутов → static → inter-VLAN → OSPF → сравнение с BGP', 'Настроить маршруты, проследить longest-prefix match, восстановить соседство'),
 ('DHCP и DNS', [10,11,55,56], [9,10,29,30], 'DORA → пул и параметры → разрешение имени → записи и диагностика', 'Упорядочить DORA; исправить пул; пошагово разрешить имя'),
 ('NAT и PAT', [8,57], [11,12], 'Трансляция адреса → трансляция порта → обратный трафик', 'Наблюдать таблицу трансляций для двух клиентов и исправить настройку'),
 ('Беспроводные сети', [4,41], [4,35], 'Wi-Fi и Bluetooth → SSID → WPA2/WPA3', 'Настроить точку доступа и сравнить подключения с разными параметрами'),
 ('Серверы и инфраструктура', [14,15,16,18], [], 'Windows Server/Linux → периферия → виртуализация → внедрение изменений', 'Соединить роли и службы; подключить принтер; выбрать план миграции'),
 ('Диагностика и наблюдение', [26,29,30,59], [25,26,27,31,32], 'ping/tracert/netstat → ICMP/DNS в захвате → метрики → журналы', 'Диагностический терминал, разбор пакетов и временной шкалы сбоя'),
 ('Политики и защита сети', [7,25,27,28,34,37,38,40,58], [21,22,33,34,38], 'Политики и угрозы → ACL/firewall → IDS → конечные устройства → физическая защита', 'Переставить правила ACL; проверить пакеты; классифицировать события IDS'),
 ('TLS, VPN и управление доступом', [31,32,33,35,36,39], [23,24], 'Аутентификация и права → MFA → TLS → IPsec/L2TP → удалённый доступ', 'Проверить сертификат, выбрать факторы, восстановить параметры туннеля'),
 ('Облако, IoT и новые угрозы', [12,13,43,44,45,46,47,48], [37], 'Гибридная сеть → IoT → разделённая ответственность → защита облачных данных', 'Спроектировать сегментацию и доступ; найти ошибки в схеме облачного хранения'),
 ('Восстановление и итоговая сеть', [42,60], [36,39,40], 'Резервные копии → восстановление → комплексная диагностика → защита проекта', 'Восстановить сервис; собрать корпоративную сеть и устранить набор неисправностей'),
]

mapping = {}
for number, (title, theory, practice, lessons, interactive) in enumerate(modules, 1):
    for kind, ids in [('theory', theory), ('practice', practice)]:
        for i in ids:
            assert (kind, i) not in mapping
            mapping[kind, i] = number
assert set(mapping) == {(kind, q['number']) for kind, questions in source.items() for q in questions}

e = escape
rows = []
for kind, label in [('theory', 'Т'), ('practice', 'П')]:
    for q in source[kind]:
        n = mapping[kind, q['number']]
        destination = f'М{n:02d} / ' + ('урок' if kind == 'theory' else 'экзаменационная практика') + f' {label}{q["number"]:02d}'
        rows.append(f'<tr><th>{label}{q["number"]:02d}</th><td>{e(q["title"])}</td><td>{e(destination)}<br><small>{e(modules[n-1][0])}</small></td></tr>')

cards = []
for n, (title, theory, practice, lessons, interactive) in enumerate(modules, 1):
    refs = ', '.join(f'Т{x:02d}' for x in theory) + ('; ' + ', '.join(f'П{x:02d}' for x in practice) if practice else '')
    cards.append(f'<article><span>МОДУЛЬ {n:02d}</span><h2>{e(title)}</h2><p><b>Уроки:</b> {e(lessons)}</p><p><b>Интерактив:</b> {e(interactive)}</p><p><b>Источник:</b> {refs}</p></article>')

html = '''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>План интерактивного курса — на согласование</title>
<style>body{margin:0;background:#f4f6fb;color:#1b2941;font:16px/1.6 system-ui}main{max-width:1100px;margin:auto;padding:32px 20px}h1{font-size:36px;line-height:1.2}h2{font-size:23px;margin:8px 0}article,.intro{background:white;border:1px solid #dce3ee;border-radius:16px;padding:24px;margin:16px 0}article span{font-size:12px;letter-spacing:.1em;color:#235bb0}table{border-collapse:collapse;width:100%;background:white}th,td{border:1px solid #dce3ee;padding:12px;text-align:left;vertical-align:top}thead{background:#19365e;color:white}small{color:#51627a}.table{overflow:auto}a{color:#1958b4}@media print{article,tr{break-inside:avoid}}</style>
<main><p>ПРОЕКТ ПРОГРАММЫ · НУЖНО ПОДТВЕРЖДЕНИЕ</p><h1>Компьютерные сети: понять → попробовать → объяснить</h1>
<div class="intro"><p><b>Источник:</b> существующий content.json: 60 вопросов теории и 40 практических заданий. В новом вложении есть техническое задание, но нет отдельного списка экзаменационных вопросов. Исходные формулировки ниже сохранены без изменений.</p>
<p><b>Цикл:</b> цель → короткий урок с интерактивной схемой → 3–5 проверок с объяснениями → практика → итог модуля. У каждого теоретического вопроса будет краткий экзаменационный ответ и развёрнутое объяснение. Учебные мини-задания — производные от вопросов источника, а не новые экзаменационные темы.</p>
<p><b>Порог:</b> минимум 70/100 за итоговый тест и выполнение обязательных практик. Автоматические задания проверяет сервер; свободные ответы и внешние лабораторные — преподаватель. Для них проходной балл также 70. Преподаватель может открыть следующий модуль вручную с фиксацией причины. Повторные попытки доступны, ошибки формируют очередь повторения. Тренировочные подсказки стоят 5 баллов за каждую подсказку в конкретном задании, нижняя граница — 0; экзамен проходит без подсказок.</p>
<p><b>Сохранность:</b> существующие работы, аккаунты и оценки не удаляются и не перенумеровываются. Новый маршрут курса использует отдельные идентификаторы модулей; старый журнал сохраняется как история. После согласования отдельно проверяется перенос прогресса.</p></div>
<h2>Последовательность модулей</h2>''' + ''.join(cards) + '''
<section class="intro"><h2>Первый образцовый модуль</h2><p>М01: клиент и сервер; устройства и интерфейсы; путь данных и роль протоколов. 6 коротких уроков по вопросам Т01, Т03, Т05, Т06, Т21, Т22; по 3–5 проверок после каждого. Практика: собрать схему офиса из устройств, провести запрос, объяснить выбор коммутатора и маршрутизатора. Итоговый тест покрывает все 6 вопросов. Глубокая настройка маршрутов изучается позже, после IP-адресации.</p><p>Проверки: выбор, сопоставление и порядок шагов. Конструктор поддерживает мышь и клавиатуру. Прогресс хранится на сервере, кнопка «Продолжить» возвращает к текущему шагу. Преподаватель видит попытки и итог. Эталон сначала проверяется отдельно, без замены рабочего сайта, затем согласуется.</p></section>
<section class="intro"><h2>Границы симуляций</h2><p>OSI/TCP-IP, ARP, TCP и STP объясняют механизмы из вопросов о протоколах, Ethernet, коммутации и диагностике; отдельных новых экзаменационных разделов не добавляется. VLSM — дополнительное усложнение subnetting, а не обязательный экзаменационный пункт, поскольку его нет в исходном списке. Учебный терминал поддерживает явно перечисленные команды и не выдаётся за полноценный Cisco IOS/Linux. Исходные практики Packet Tracer, Wireshark и VPN остаются доступными для сдачи преподавателю.</p></section>
<h2>Покрытие: все 100 пунктов</h2><p>Т — теория; П — практика. У каждого пункта ровно один основной учебный адрес. Связанные уроки дополнительно ссылаются друг на друга.</p><div class="table"><table><thead><tr><th>№</th><th>Исходный вопрос / задание</th><th>Урок / практика</th></tr></thead><tbody>''' + ''.join(rows) + '</tbody></table></div></main></html>'
(ROOT / 'docs/course-plan.html').write_text(html, encoding='utf-8')
print(f'Coverage verified: {len(mapping)} / 100, modules: {len(modules)}')

